import { useState, useCallback, type KeyboardEvent, type ChangeEvent } from 'react';
import { Stack, Tag, TextField } from '@jinx-ui/react';

// API names (TextField / Tag.onRemove / Stack) assumed from Jinx UI conventions — verify against the installed version.

type ArticleTagPickerProps = {
  label?: string;
  placeholder?: string;
  initialTags?: string[];
  maxTags?: number;
  onChange?: (tags: string[]) => void;
};

function ArticleTagPicker({
  label = 'Теги статьи',
  placeholder = 'Введите тег и нажмите Enter',
  initialTags = [],
  maxTags = 10,
  onChange,
}: ArticleTagPickerProps) {
  const [tags, setTags] = useState<string[]>(initialTags);
  const [draft, setDraft] = useState('');

  const commit = useCallback(
    (raw: string) => {
      const next = raw.trim().replace(/\s+/g, ' ');
      if (!next) return;
      if (tags.length >= maxTags) return;
      if (tags.some((tag) => tag.toLowerCase() === next.toLowerCase())) {
        setDraft('');
        return;
      }
      const updated = [...tags, next];
      setTags(updated);
      setDraft('');
      onChange?.(updated);
    },
    [tags, maxTags, onChange],
  );

  const remove = useCallback(
    (target: string) => {
      const updated = tags.filter((tag) => tag !== target);
      setTags(updated);
      onChange?.(updated);
    },
    [tags, onChange],
  );

  const handleKeyDown = (event: KeyboardEvent<HTMLInputElement>) => {
    if (event.key === 'Enter' || event.key === ',') {
      event.preventDefault();
      commit(draft);
      return;
    }
    if (event.key === 'Backspace' && draft === '' && tags.length > 0) {
      remove(tags[tags.length - 1]);
    }
  };

  const isFull = tags.length >= maxTags;

  return (
    <Stack direction="column" style={{ gap: 'var(--jx-space-2)' }}>
      <TextField
        label={label}
        value={draft}
        placeholder={isFull ? `Достигнут предел: ${maxTags}` : placeholder}
        disabled={isFull}
        hint={`${tags.length} из ${maxTags}`}
        onChange={(event: ChangeEvent<HTMLInputElement>) => setDraft(event.target.value)}
        onKeyDown={handleKeyDown}
        onBlur={() => commit(draft)}
      />

      {tags.length > 0 && (
        <Stack direction="row" wrap style={{ gap: 'var(--jx-space-1)' }}>
          {tags.map((tag) => (
            <Tag key={tag} onRemove={() => remove(tag)} removeLabel={`Удалить тег ${tag}`}>
              {tag}
            </Tag>
          ))}
        </Stack>
      )}
    </Stack>
  );
}

export default ArticleTagPicker;

